34	const pendingReviewMarkerFilename = "review-pending.json"
35	
36	// PendingReviewMarker is written by `entire review` before spawning the agent.
37	// The next agent session's UserPromptSubmit hook reads it, tags the session
38	// kind/review-skills, then clears the marker (so a second review run doesn't
39	// inherit state from the first).
40	//
41	// WorktreePath scopes the marker to the worktree `entire review` was invoked
42	// from: multiple worktrees in one repo share .git/entire-sessions/, so without
43	// this field any session in any worktree could race to claim the marker. A
44	// blank WorktreePath (pre-fix markers) falls back to the legacy unscoped
45	// behavior — any session can adopt.
46	type PendingReviewMarker struct {
47		AgentName    string    `json:"agent_name"`
48		Skills       []string  `json:"skills"`
49		StartingSHA  string    `json:"starting_sha"`
50		StartedAt    time.Time `json:"started_at"`
51		WorktreePath string    `json:"worktree_path,omitempty"`
52	}
53	
54	func pendingMarkerPath(ctx context.Context) (string, error) {
55		commonDir, err := session.GetGitCommonDir(ctx)
56		if err != nil {
57			return "", fmt.Errorf("locate git common dir: %w", err)
58		}
59		return filepath.Join(commonDir, session.SessionStateDirName, pendingReviewMarkerFilename), nil
60	}
61	
62	// WritePendingReviewMarker persists the marker. Overwrites any existing marker.
63	func WritePendingReviewMarker(ctx context.Context, m PendingReviewMarker) error {
64		path, err := pendingMarkerPath(ctx)
65		if err != nil {
66			return err
67		}
68		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
69			return fmt.Errorf("create sessions dir: %w", err)
70		}
71		data, err := json.MarshalIndent(m, "", "  ")
72		if err != nil {
73			return fmt.Errorf("marshal marker: %w", err)
74		}
75		if err := os.WriteFile(path, data, 0o600); err != nil {
76			return fmt.Errorf("write marker: %w", err)
77		}
78		return nil
79	}
80	
81	// ReadPendingReviewMarker returns the marker if one exists.
82	// ok=false with err=nil indicates "no pending review."
83	func ReadPendingReviewMarker(ctx context.Context) (PendingReviewMarker, bool, error) {
84		path, err := pendingMarkerPath(ctx)
85		if err != nil {
86			return PendingReviewMarker{}, false, err
87		}
88		data, err := os.ReadFile(path) //nolint:gosec // path derived from git dir
89		if errors.Is(err, os.ErrNotExist) {
90			return PendingReviewMarker{}, false, nil
91		}
92		if err != nil {
93			return PendingReviewMarker{}, false, fmt.Errorf("read marker: %w", err)
94		}
95		var m PendingReviewMarker
96		if err := json.Unmarshal(data, &m); err != nil {
97			return PendingReviewMarker{}, false, fmt.Errorf("parse marker: %w", err)
98		}
99		return m, true, nil
100	}
101	
102	// ClearPendingReviewMarker removes the marker. Missing file is not an error.
103	func ClearPendingReviewMarker(ctx context.Context) error {
104		path, err := pendingMarkerPath(ctx)
105		if err != nil {
106			return err
107		}
108		if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
109			return fmt.Errorf("remove marker: %w", err)
110		}
111		return nil
112	}
