294	func newReviewCmd() *cobra.Command {
295		var edit bool
296		var trackOnly bool
297	
298		cmd := &cobra.Command{
299			Use:   "review",
300			Short: "Run configured review skills against the current branch",
301			Long: `Run the review skills configured in .entire/settings.json against
302	the current branch. On first run, an interactive picker writes the config.
303	
304	The review session is recorded as part of the next checkpoint, so the
305	review metadata is permanently attached to the commit it covers.`,
306			RunE: func(cmd *cobra.Command, _ []string) error {
307				ctx := cmd.Context()
308				if edit {
309					_, err := runReviewConfigPicker(ctx, cmd.OutOrStdout())
310					return err
311				}
312				return runReview(ctx, cmd, trackOnly)
313			},
314		}
315		cmd.Flags().BoolVar(&edit, "edit", false, "re-open the review config picker")
316		cmd.Flags().BoolVar(&trackOnly, "track-only", false, "write pending marker without spawning agent")
317		return cmd
318	}
319	
320	func runReview(ctx context.Context, cmd *cobra.Command, trackOnly bool) error {
321		out := cmd.OutOrStdout()
322	
323		// 1. Pre-flight: must be in a git repo.
324		if _, err := paths.WorktreeRoot(ctx); err != nil {
325			cmd.SilenceUsage = true
326			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run `entire enable` first.")
327			return NewSilentError(errors.New("not a git repository"))
328		}
329	
330		// 2. Load config. A load error means the settings file exists but is
331		// malformed (Load returns a default-filled object when the file is
332		// missing). Surface the error instead of silently opening the picker,
333		// which would cause saveReviewConfig to write over the user's other
334		// settings with an empty EntireSettings{}.
335		s, err := settings.Load(ctx)
336		if err != nil {
337			cmd.SilenceUsage = true
338			fmt.Fprintf(cmd.ErrOrStderr(), "Failed to load settings: %v\n", err)
339			fmt.Fprintln(cmd.ErrOrStderr(), "Fix `.entire/settings.json` and re-run `entire review`.")
340			return NewSilentError(err)
341		}
342		if s == nil || len(s.Review) == 0 {
343			picked, pickErr := runReviewConfigPicker(ctx, out)
344			if pickErr != nil {
345				return pickErr
346			}
347			if s == nil {
348				s = &settings.EntireSettings{}
349			}
350			s.Review = picked
351		}
352	
353		// 3. Pick agent.
354		agentName, skills, err := selectReviewAgent(s.Review)
355		if err != nil {
356			return err
357		}
358	
359		// 4. Re-run guard: check if HEAD's checkpoint already has a review.
360		if reviewed, meta := headHasReviewCheckpoint(ctx); reviewed {
361			var proceed bool
362			form := NewAccessibleForm(huh.NewGroup(
363				huh.NewConfirm().
364					Title(fmt.Sprintf("Already reviewed: %s. Proceed anyway?", meta)).
365					Value(&proceed),
366			))
367			if err := form.Run(); err != nil {
368				fmt.Fprintln(out, "prompt cancelled")
369				return err //nolint:wrapcheck // propagate huh cancellation
370			}
371			if !proceed {
372				fmt.Fprintln(out, "Review cancelled.")
373				return nil
374			}
375		}
376	
377		// 5. Resolve HEAD + worktree root for the pending marker. WorktreePath
378		// scopes the marker so that a session in *another* worktree sharing the
379		// same .git/ can't race to claim it.
380		headSHA, err := currentHeadSHA(ctx)
381		if err != nil {
382			return fmt.Errorf("resolve HEAD: %w", err)
383		}
384		worktreeRoot, err := paths.WorktreeRoot(ctx)
385		if err != nil {
386			return fmt.Errorf("resolve worktree root: %w", err)
387		}
388	
389		// 6. Write pending marker (agent hook will adopt it).
390		if err := WritePendingReviewMarker(ctx, PendingReviewMarker{
391			AgentName:    agentName,
392			Skills:       skills,
393			StartingSHA:  headSHA,
394			StartedAt:    time.Now().UTC(),
395			WorktreePath: worktreeRoot,
396		}); err != nil {
397			return fmt.Errorf("write pending marker: %w", err)
398		}
399	
400		if trackOnly {
401			// Marker must persist — the user will start the agent manually and
402			// its hook will adopt the marker.
403			fmt.Fprintln(out, "Pending review marker written.")
404			fmt.Fprintf(out, "Start %s and run these skills manually: %s\n", agentName, strings.Join(skills, ", "))
405			return nil
406		}
407	
408		// From this point on, the marker lives on disk until either (a) the
409		// spawned agent's hook adopts and clears it, or (b) we clear it here
410		// as a fallback. The defer covers every spawn/launch/run failure path,
411		// and also the case where the agent exits cleanly without ever firing
412		// UserPromptSubmit (e.g. user `/quit`s immediately). Leaving the marker
413		// in those cases would mis-tag the next unrelated session as a review.
414		defer func() {
415			_, exists, readErr := ReadPendingReviewMarker(ctx)
416			if readErr != nil || !exists {
417				return
418			}
419			if clearErr := ClearPendingReviewMarker(ctx); clearErr != nil {
420				logging.Debug(ctx, "cleanup unadopted review marker", slog.String("error", clearErr.Error()))
421			}
422		}()
423	
424		// 7. Spawn agent with the composed initial prompt.
425		launcher, ok := agent.LauncherFor(types.AgentName(agentName))
426		if !ok {
427			fmt.Fprintf(out, "%s does not support subprocess launch yet. Falling back to --track-only.\n", agentName)
428			fmt.Fprintf(out, "Start %s manually and run: %s\n", agentName, strings.Join(skills, ", "))
429			return nil
430		}
431		// Best-effort: show the user what's in scope so they can tell whether
432		// the review target is what they expected. Failures are silent — scope
433		// is informational, not load-bearing.
434		if scope, scopeErr := detectReviewScope(ctx); scopeErr == nil {
435			fmt.Fprintln(out, formatReviewScope(scope))
436		}
437		prompt := composeReviewPrompt(skills)
438		execCmd, err := launcher.LaunchCmd(ctx, prompt)
439		if err != nil {
440			return fmt.Errorf("launch %s: %w", agentName, err)
441		}
442		if err := execCmd.Run(); err != nil {
443			return fmt.Errorf("agent exited: %w", err)
444		}
445		return nil
446	}
447	
448	// selectReviewAgent picks an agent from the configured review map. v1: single
449	// agent. If multiple are configured, returns the one that sorts first by name
450	// (deterministic default). Returns an error if the map is empty.
451	func selectReviewAgent(review map[string][]string) (string, []string, error) {
452		if len(review) == 0 {
453			return "", nil, errors.New("no review skills configured")
454		}
455		// Deterministic pick: alphabetical by agent name.
456		var names []string
457		for name, skills := range review {
458			if len(skills) > 0 {
459				names = append(names, name)
460			}
461		}
462		if len(names) == 0 {
463			return "", nil, errors.New("no review skills configured")
464		}
465		sort.Strings(names)
466		pick := names[0]
467		return pick, review[pick], nil
468	}
469	
470	// composeReviewPrompt builds the initial prompt the agent receives.
471	func composeReviewPrompt(skills []string) string {
472		var sb strings.Builder
473		sb.WriteString("Please run these review skills in order:\n")
474		for i, skill := range skills {
475			fmt.Fprintf(&sb, "  %d. %s\n", i+1, skill)
476		}
477		return sb.String()
478	}
