480	// currentHeadSHA returns the current HEAD commit hash as a 40-char hex string.
481	func currentHeadSHA(ctx context.Context) (string, error) {
482		repoRoot, err := paths.WorktreeRoot(ctx)
483		if err != nil {
484			return "", fmt.Errorf("locate repo root: %w", err)
485		}
486		execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "rev-parse", "HEAD")
487		output, err := execCmd.Output()
488		if err != nil {
489			return "", fmt.Errorf("git rev-parse HEAD: %w", err)
490		}
491		return strings.TrimSpace(string(output)), nil
492	}
493	
494	// reviewScope summarizes what's about to be reviewed, surfaced to the user
495	// before the agent launches. Zero-valued fields mean "not detected" — format
496	// helpers degrade gracefully.
497	type reviewScope struct {
498		Branch       string // current branch short name; "" if detached
499		HeadSHA      string // short HEAD SHA (always set when non-empty scope)
500		Base         string // base branch (e.g. "main"); "" if unknown
501		AheadCommits int    // commits in base..HEAD; 0 if Base == ""
502		FilesChanged int    // files in base..HEAD diff; 0 if Base == ""
503		Uncommitted  int    // files from `git status --porcelain`
504	}
505	
506	// detectReviewScope runs a handful of cheap `git` queries to describe the
507	// set of changes the user is about to review. Best-effort: any individual
508	// query that fails leaves the corresponding field at its zero value.
509	func detectReviewScope(ctx context.Context) (reviewScope, error) {
510		repoRoot, err := paths.WorktreeRoot(ctx)
511		if err != nil {
512			return reviewScope{}, fmt.Errorf("locate repo root: %w", err)
513		}
514		var s reviewScope
515		s.Branch = gitString(ctx, repoRoot, "rev-parse", "--abbrev-ref", "HEAD")
516		if s.Branch == detachedHEADDisplay {
517			s.Branch = ""
518		}
519		s.HeadSHA = gitString(ctx, repoRoot, "rev-parse", "--short", "HEAD")
520		s.Base = detectBaseBranch(ctx, repoRoot)
521		if s.Base != "" && s.Branch != "" && s.Base != s.Branch {
522			if n, ok := gitCount(ctx, repoRoot, "rev-list", "--count", s.Base+".."+s.Branch); ok {
523				s.AheadCommits = n
524			}
525			if files := gitString(ctx, repoRoot, "diff", "--name-only", s.Base+"..."+s.Branch); files != "" {
526				s.FilesChanged = len(strings.Split(files, "\n"))
527			}
528		}
529		if status := gitString(ctx, repoRoot, "status", "--porcelain"); status != "" {
530			s.Uncommitted = len(strings.Split(status, "\n"))
531		}
532		return s, nil
533	}
534	
535	// detectBaseBranch resolves a base branch name by trying, in order:
536	// origin/HEAD → origin/main → origin/master → local main → local master.
537	// Returns "" if none match. Remote-tracking branches come first because they
538	// reflect the team's convention; local branches are the fallback for repos
539	// that haven't been `git fetch`'d recently.
540	func detectBaseBranch(ctx context.Context, repoRoot string) string {
541		if target := gitString(ctx, repoRoot, "symbolic-ref", "--short", "refs/remotes/origin/HEAD"); target != "" {
542			return strings.TrimPrefix(target, "origin/")
543		}
544		candidates := []string{defaultBaseBranch, masterBaseBranch}
545		for _, candidate := range candidates {
546			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/remotes/origin/"+candidate) {
547				return candidate
548			}
549		}
550		for _, candidate := range candidates {
551			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/heads/"+candidate) {
552				return candidate
553			}
554		}
555		return ""
556	}
557	
558	// gitString runs `git -C repoRoot <args...>` and returns trimmed stdout, or
559	// "" on any error.
560	func gitString(ctx context.Context, repoRoot string, args ...string) string {
561		full := append([]string{"-C", repoRoot}, args...)
562		out, err := exec.CommandContext(ctx, "git", full...).Output()
563		if err != nil {
564			return ""
565		}
566		return strings.TrimSpace(string(out))
567	}
568	
569	// gitOK runs `git -C repoRoot <args...>` and reports whether it succeeded.
570	func gitOK(ctx context.Context, repoRoot string, args ...string) bool {
571		full := append([]string{"-C", repoRoot}, args...)
572		return exec.CommandContext(ctx, "git", full...).Run() == nil
573	}
574	
575	// gitCount runs a git command expected to output an integer and parses it.
576	func gitCount(ctx context.Context, repoRoot string, args ...string) (int, bool) {
577		s := gitString(ctx, repoRoot, args...)
578		if s == "" {
579			return 0, false
580		}
581		n, err := strconv.Atoi(s)
582		if err != nil {
583			return 0, false
584		}
585		return n, true
586	}
