615	// headHasReviewCheckpoint checks whether HEAD's checkpoint metadata includes
616	// a review session. Returns (true, infoString) if HasReview is set.
617	// Single lookup: read the Entire-Checkpoint trailer from HEAD, then resolve
618	// the CheckpointSummary via ResolveCommittedReaderForCheckpoint so v2-enabled
619	// repos also work (v1 alone would miss v2-written summaries).
620	//
621	// Each early return logs at Debug so users debugging "why is no review badge
622	// showing?" have breadcrumbs without the caller having to ask for five
623	// distinct failure modes.
624	func headHasReviewCheckpoint(ctx context.Context) (bool, string) {
625		repoRoot, err := paths.WorktreeRoot(ctx)
626		if err != nil {
627			logging.Debug(ctx, "head review check: locate worktree root", slog.String("error", err.Error()))
628			return false, ""
629		}
630		execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "-1", "--format=%B")
631		output, err := execCmd.Output()
632		if err != nil {
633			logging.Debug(ctx, "head review check: read HEAD commit message", slog.String("error", err.Error()))
634			return false, ""
635		}
636		cpID, ok := trailers.ParseCheckpoint(string(output))
637		if !ok {
638			logging.Debug(ctx, "head review check: no Entire-Checkpoint trailer on HEAD")
639			return false, ""
640		}
641		repo, err := git.PlainOpen(repoRoot)
642		if err != nil {
643			logging.Debug(ctx, "head review check: open repository", slog.String("error", err.Error()))
644			return false, ""
645		}
646		v1Store := checkpoint.NewGitStore(repo)
647		v2URL, urlErr := remote.FetchURL(ctx)
648		if urlErr != nil {
649			logging.Debug(ctx, "head review check: no configured v2 fetch remote", slog.String("error", urlErr.Error()))
650			v2URL = ""
651		}
652		v2Store := checkpoint.NewV2GitStore(repo, v2URL)
653		_, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, v1Store, v2Store, settings.IsCheckpointsV2Enabled(ctx))
654		if err != nil || summary == nil {
655			logging.Debug(ctx, "head review check: resolve checkpoint summary",
656				slog.String("checkpoint_id", cpID.String()),
657				slog.Any("error", err))
658			return false, ""
659		}
660		if !summary.HasReview {
661			logging.Debug(ctx, "head review check: summary HasReview is false", slog.String("checkpoint_id", cpID.String()))
662			return false, ""
663		}
664		return true, fmt.Sprintf("checkpoint %s", cpID)
665	}
