667	// saveReviewConfig persists the review map into .entire/settings.json while
668	// preserving all other settings. A Load error means the file exists but is
669	// malformed — we must NOT silently overwrite it with an empty struct, or
670	// every unrelated setting the user had configured would be wiped. Return the
671	// error so the caller can surface it instead.
672	func saveReviewConfig(ctx context.Context, review map[string][]string) error {
673		s, err := settings.Load(ctx)
674		if err != nil {
675			return fmt.Errorf("load settings before save: %w", err)
676		}
677		if s == nil {
678			s = &settings.EntireSettings{}
679		}
680		s.Review = review
681		if err := settings.Save(ctx, s); err != nil {
682			return fmt.Errorf("save settings: %w", err)
683		}
684		return nil
685	}
