38	func newAttachCmd() *cobra.Command {
39		var (
40			force     bool
41			agentFlag string
42		)
43		cmd := &cobra.Command{
44			Use:   "attach <session-id>",
45			Short: "Attach an existing agent session",
46			Long: `Attach an existing agent session that wasn't captured by hooks.
47	
48	This creates a checkpoint from the session's transcript and links it to the
49	last commit. Use this when hooks failed to fire or weren't installed when
50	the session started, or to attach a research session.
51	
52	If the last commit already has a checkpoint, the session is added to it.
53	Otherwise a new checkpoint is created.
54	
55	Works with any registered agent, including external agents enabled via
56	external_agents in settings. Run 'entire configure' to see the full list.`,
57			RunE: func(cmd *cobra.Command, args []string) error {
58				if len(args) != 1 {
59					return cmd.Help()
60				}
61				if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
62					return nil
63				}
64				// Discover external agents so --agent <external-name> is recognized
65				// and so auto-detection can find transcripts from external agents.
66				external.DiscoverAndRegister(cmd.Context())
67				agentName := types.AgentName(agentFlag)
68				return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
69			},
70		}
