76	func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
77		// Initialize structured logger so logging.Warn/Info write to .entire/logs/ not stderr.
78		if err := logging.Init(ctx, sessionID); err != nil {
79			// Init failed — logging will use stderr fallback, non-fatal.
80			_ = err
81		}
82	
83		logCtx := logging.WithComponent(ctx, "attach")
84	
85		// Open repository once — shared across all operations.
86		repo, err := openRepository(ctx)
87		if err != nil {
88			return err
89		}
90	
91		existingState, err := validateAttachPreconditions(ctx, repo, sessionID)
92		if err != nil {
93			return err
94		}
95	
96		headCommit, err := getHeadCommit(repo)
97		if err != nil {
98			return err
99		}
100	
101		// If session already has a checkpoint, just offer to link it.
102		if existingState != nil && !existingState.LastCheckpointID.IsEmpty() {
103			cpID := existingState.LastCheckpointID.String()
104			fmt.Fprintf(w, "Session %s already has checkpoint %s\n", sessionID, cpID)
105			if err := promptAmendCommit(logCtx, w, headCommit, cpID, force); err != nil {
106				logging.Warn(logCtx, "failed to amend commit", "error", err)
107				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpID)
108			}
109			return nil
110		}
111	
112		// Resolve agent and transcript path.
113		ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName, existingState)
114		if err != nil {
115			return err
116		}
117	
118		transcriptData, err := ag.ReadTranscript(transcriptPath)
119		if err != nil {
120			return fmt.Errorf("failed to read transcript: %w", err)
121		}
122	
123		// Normalize Gemini transcripts for storage.
124		storedTranscript := transcriptData
125		if ag.Type() == agent.AgentTypeGemini {
126			if normalized, normErr := geminicli.NormalizeTranscript(transcriptData); normErr == nil {
127				storedTranscript = normalized
128			} else {
129				logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
130			}
131		}
132	
133		meta := extractTranscriptMetadata(transcriptData)
134	
135		// Determine checkpoint ID: reuse from HEAD if one exists, otherwise generate new.
136		checkpointID, isExistingCheckpoint := resolveCheckpointID(headCommit)
137	
138		// Write directly to entire/checkpoints/v1.
139		store := cpkg.NewGitStore(repo)
140	
141		author, err := GetGitAuthor(ctx)
142		if err != nil {
143			return fmt.Errorf("failed to get git author: %w", err)
144		}
145	
146		var prompts []string
147		if meta.FirstPrompt != "" {
148			prompts = []string{meta.FirstPrompt}
149		}
150	
151		tokenUsage := agent.CalculateTokenUsage(logCtx, ag, transcriptData, 0, "")
152	
153		_, redactSpan := perf.Start(ctx, "redact_transcript")
154		redactedTranscript, redactErr := redact.JSONLBytes(storedTranscript)
155		redactSpan.End()
156		if redactErr != nil {
157			return fmt.Errorf("failed to redact transcript: %w", redactErr)
158		}
159	
160		writeOpts := cpkg.WriteCommittedOptions{
161			CheckpointID: checkpointID,
162			SessionID:    sessionID,
163			Strategy:     strategy.StrategyNameManualCommit,
164			Transcript:   redactedTranscript,
165			Prompts:      prompts,
166			AuthorName:   author.Name,
167			AuthorEmail:  author.Email,
168			Agent:        ag.Type(),
169			Model:        meta.Model,
170			TokenUsage:   tokenUsage,
171		}
172	
173		if compacted := compactTranscriptForStartLine(logCtx, redactedTranscript.Bytes(), cpkg.CommittedMetadata{
174			CheckpointID: checkpointID,
175			Agent:        ag.Type(),
176		}, 0); compacted != nil {
177			writeOpts.CompactTranscript = compacted
178		}
179	
180		v2 := settings.CheckpointsVersion(logCtx) == 2
181		if !v2 {
182			if err := store.WriteCommitted(ctx, writeOpts); err != nil {
183				return fmt.Errorf("failed to write checkpoint: %w", err)
184			}
185		}
186		// IsCheckpointsV2Enabled is true whenever v2 writes are enabled, including
187		// both v2-only mode (checkpoints_version == 2) and dual-write mode. Only
188		// v2-only mode propagates the error.
189		if settings.IsCheckpointsV2Enabled(logCtx) {
