219	// writeAttachCheckpointV2 writes attach-created checkpoints into the v2 refs.
220	func writeAttachCheckpointV2(ctx context.Context, repo *git.Repository, opts cpkg.WriteCommittedOptions) error {
221		v2URL, err := remote.FetchURL(ctx)
222		if err != nil {
223			logging.Debug(ctx, "attach: using origin for v2 store fetch remote",
224				slog.String("error", err.Error()),
225			)
226		}
227		v2Store := cpkg.NewV2GitStore(repo, v2URL)
228		if err := v2Store.WriteCommitted(ctx, opts); err != nil {
229			return fmt.Errorf("v2 write committed: %w", err)
230		}
231		return nil
232	}
233	
234	// getHeadCommit returns the HEAD commit object.
235	func getHeadCommit(repo *git.Repository) (*object.Commit, error) {
236		headRef, err := repo.Head()
237		if err != nil {
238			return nil, fmt.Errorf("failed to get HEAD: %w", err)
239		}
240		commit, err := repo.CommitObject(headRef.Hash())
241		if err != nil {
242			return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
243		}
244		return commit, nil
245	}
246	
247	// resolveCheckpointID returns the checkpoint ID to use for the attach.
248	// If HEAD already has an Entire-Checkpoint trailer, reuses that ID (the session
249	// gets added as an additional session in the existing checkpoint).
250	// Otherwise generates a new ID.
251	func resolveCheckpointID(headCommit *object.Commit) (id.CheckpointID, bool) {
252		existing := trailers.ParseAllCheckpoints(headCommit.Message)
253		if len(existing) > 0 {
254			return existing[len(existing)-1], true
255		}
256	
257		cpID, err := id.Generate()
258		if err != nil {
259			// Generation only fails if crypto/rand fails — extremely unlikely.
260			// Fall back to empty which will cause WriteCommitted to fail with a clear error.
261			return id.EmptyCheckpointID, false
262		}
263		return cpID, false
264	}
265	
266	// saveAttachSessionState creates or updates the session state file for the attached session.
267	// If existingState is non-nil, it is updated in place (avoids a redundant disk load).
268	func saveAttachSessionState(ctx context.Context, existingState *session.State, sessionID string, agentType types.AgentType, transcriptPath string, checkpointID id.CheckpointID, meta transcriptMetadata, tokenUsage *agent.TokenUsage) error {
269		stateStore, err := session.NewStateStore(ctx)
270		if err != nil {
271			return fmt.Errorf("failed to open session store: %w", err)
272		}
273	
274		now := time.Now()
275		state := existingState
276		if state == nil {
277			state = &session.State{
278				SessionID: sessionID,
