309	// validateAttachPreconditions checks session ID format and git repo state.
310	// Returns the existing session state if the session is already tracked (nil if new).
311	func validateAttachPreconditions(ctx context.Context, repo *git.Repository, sessionID string) (*session.State, error) {
312		if err := validation.ValidateSessionID(sessionID); err != nil {
313			return nil, fmt.Errorf("invalid session ID: %w", err)
314		}
315	
316		if strategy.IsEmptyRepository(repo) {
317			return nil, errors.New("repository has no commits yet — make an initial commit before running attach")
318		}
319	
320		store, err := session.NewStateStore(ctx)
321		if err != nil {
322			return nil, fmt.Errorf("failed to open session store: %w", err)
323		}
324		existing, err := store.Load(ctx, sessionID)
325		if err != nil {
326			return nil, fmt.Errorf("failed to check existing session: %w", err)
327		}
328	
329		return existing, nil
330	}
