332	// resolveAgentAndTranscript resolves the agent and transcript path.
333	// For existing sessions, resolves the agent from session state's AgentType.
334	// For new sessions, uses the --agent flag with auto-detection fallback.
335	func resolveAgentAndTranscript(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, existingState *session.State) (agent.Agent, string, error) {
336		ag, err := resolveAgent(existingState, agentName)
337		if err != nil {
338			return nil, "", err
339		}
340	
341		transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
342		if err != nil {
343			// Auto-detect: try all other agents.
344			detectedAg, detectedPath, detectErr := detectAgentByTranscript(ctx, sessionID, agentName)
345			if detectErr != nil {
346				return nil, "", fmt.Errorf("%w (also tried auto-detecting other agents: %w)", err, detectErr)
347			}
348			ag = detectedAg
349			transcriptPath = detectedPath
350			logging.Info(ctx, "auto-detected agent from transcript", "agent", ag.Name())
351			fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
352		}
353	
354		return ag, transcriptPath, nil
355	}
356	
357	// resolveAgent resolves the agent to use. For existing sessions with an AgentType,
358	// uses agent.GetByAgentType. Otherwise falls back to the --agent flag.
359	func resolveAgent(existingState *session.State, agentName types.AgentName) (agent.Agent, error) {
360		if existingState != nil && existingState.AgentType != "" {
361			ag, err := agent.GetByAgentType(existingState.AgentType)
362			if err == nil {
363				return ag, nil
364			}
365			// Fall through to flag-based resolution.
366		}
367		ag, err := agent.Get(agentName)
368		if err != nil {
369			return nil, fmt.Errorf("agent %q not available: %w", agentName, err)
370		}
371		return ag, nil
372	}
373	
374	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
375	// project directories if needed.
376	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
377		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
378		if err != nil {
379			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
380		}
381		// Only call PrepareTranscript when the file already exists — it flushes
382		// in-progress writes, but can't conjure a file that was never started.
383		// This avoids agents like Cursor polling for 3s on non-existent files
384		// during auto-detection.
385		if _, statErr := os.Stat(transcriptPath); statErr == nil {
386			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
387				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
388					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
389				}
390			}
391			return transcriptPath, nil
392		}
393		found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
394		if searchErr == nil {
395			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
396			return found, nil
397		}
398		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
399		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
400	}
401	
402	// detectAgentByTranscript tries all registered agents (except skip) to find one whose
403	// transcript resolution succeeds for the given session ID.
404	func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
405		for _, name := range agent.List() {
406			if name == skip {
407				continue
408			}
409			ag, err := agent.Get(name)
410			if err != nil {
411				continue
412			}
413			path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
414			if resolveErr != nil {
415				logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
416				continue
417			}
418			return ag, path, nil
419		}
420		return nil, "", errors.New("transcript not found for any registered agent")
421	}
422	
423	// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
424	// When force is true, it amends without prompting.
425	func promptAmendCommit(ctx context.Context, w io.Writer, headCommit *object.Commit, checkpointIDStr string, force bool) error {
426		shortHash := headCommit.Hash.String()[:7]
427		subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
428	
429		// Skip amending if this exact checkpoint ID is already in the commit.
430		for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
431			if existing.String() == checkpointIDStr {
432				fmt.Fprintf(w, "Commit %s already has Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
433				return nil
434			}
435		}
436	
437		fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
438	
439		amend := true
440		if !force {
441			if !interactive.CanPromptInteractively() {
442				// Non-interactive: can't prompt, print trailer for manual use.
443				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
444				return nil
445			}
446			form := NewAccessibleForm(
447				huh.NewGroup(
448					huh.NewConfirm().
449						Title("Amend the last commit in this branch?").
450						Affirmative("Y").
451						Negative("n").
452						Value(&amend),
453				),
454			)
455			if err := form.Run(); err != nil {
456				return fmt.Errorf("prompt failed: %w", err)
457			}
458		}
459	
460		if !amend {
461			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
462			return nil
463		}
464	
465		newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
466	
467		cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
468		if output, err := cmd.CombinedOutput(); err != nil {
469			return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
470		}
471	
472		fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
473		return nil
474	}
